import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        String engHost = "";
        int engYoq = 0;
        for (int i = 0; i < n; i++) {
            String host = in.nextLine().trim();
            int m = Integer.parseInt(in.nextLine().trim());
            int yoqotish = 0;
            int minvaqt = 1000000000;
            int maxvaqt = 0;
            for (int j = 0; j < m; j++) {
                String satr = in.nextLine().trim();
                if (satr.equals("*")) {
                    yoqotish++;
                } else {
                    int vaqt = Integer.parseInt(satr.split(" +")[1]);
                    if (vaqt < minvaqt) minvaqt = vaqt;
                    if (vaqt > maxvaqt) maxvaqt = vaqt;
                }
            }
            if (yoqotish == m) {
                System.out.println(host + " " + yoqotish + " - -");
            } else {
                System.out.println(host + " " + yoqotish + " " + minvaqt + " " + maxvaqt);
            }
            if (i == 0 || yoqotish < engYoq) {
                engHost = host;
                engYoq = yoqotish;
            }
        }
        System.out.println(engHost + " " + engYoq);
    }
}

